const scope = $('Prepare Snapshot Scope').first().json;
return [
 {json:{smartListId:5874,segmentKey:'fleet_51_100_supplement',smartListName:'Fleet Size 51-100, exact numeric 100 supplement',window_start:scope.window_start,window_end:scope.window_end}},
 {json:{smartListId:5875,segmentKey:'fleet_101_500',smartListName:'Fleet Size 101-500',window_start:scope.window_start,window_end:scope.window_end}},
 {json:{smartListId:5876,segmentKey:'fleet_500_plus',smartListName:'Fleet Size 500+',window_start:scope.window_start,window_end:scope.window_end}}
];

const { createHash } = require('crypto');
const raw = $json.data != null ? $json.data : ($json.body != null ? $json.body : '');
const text = typeof raw === 'string' ? raw : '';
if (!text.trim()) throw new Error('Marketo export file was empty');
function parseCSV(s) {
  const rows = []; let i = 0, field = '', row = [], inQ = false;
  while (i < s.length) {
    const c = s[i];
    if (inQ) {
      if (c === '"') { if (s[i + 1] === '"') { field += '"'; i++; } else inQ = false; }
      else field += c;
    } else {
      if (c === '"') inQ = true;
      else if (c === ',') { row.push(field); field = ''; }
      else if (c === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
      else if (c !== '\r') field += c;
    }
    i++;
  }
  if (inQ) throw new Error('Marketo CSV ended inside a quoted field');
  if (field.length || row.length) { row.push(field); rows.push(row); }
  return rows;
}
const clean = (v) => {
  const s = String(v == null ? '' : v).trim();
  return (s === '' || s.toLowerCase() === 'null' || s.toLowerCase() === 'undefined') ? null : s;
};
const parsed = parseCSV(text);
if (parsed.length < 1) throw new Error('Marketo export had no CSV header');
const header = parsed[0].map(h => h.trim());
if (header.some(name => !name)) throw new Error('Marketo export contains an empty CSV header');
if (new Set(header).size !== header.length) throw new Error('Marketo export contains duplicate CSV headers');
if (!header.includes('id') || !header.includes('updatedAt')) throw new Error('Marketo export missing required id/updatedAt columns');
const seen = new Set(); const rows = [];
for (let i = 1; i < parsed.length; i++) {
  const source = parsed[i];
  if (!source || (source.length === 1 && source[0] === '')) continue;
  if (source.length !== header.length) throw new Error(`Malformed Marketo CSV row ${i + 1}: expected ${header.length} columns, got ${source.length}`);
  const record = {};
  header.forEach((name, index) => { record[name] = clean(source[index]); });
  if (!record.id || !record.updatedAt) throw new Error(`Malformed Marketo CSV row ${i + 1}: missing id or updatedAt`);
  if (!/^[1-9][0-9]*$/.test(record.id)) throw new Error(`Malformed Marketo CSV row ${i + 1}: invalid numeric id`);
  if (Number.isNaN(Date.parse(record.updatedAt))) throw new Error(`Malformed Marketo CSV row ${i + 1}: invalid updatedAt timestamp`);
  if (seen.has(record.id)) throw new Error(`Duplicate Marketo id in smart-list export: ${record.id}`);
  seen.add(record.id); rows.push(record);
}
const status = $('Get Export Status').item.json.result?.[0];
if (!status || status.status !== 'Completed') throw new Error('Completed Marketo status metadata was unavailable');
const expectedRecords = Number(status.numberOfRecords);
const expectedBytes = Number(status.fileSize);
const expectedChecksum = String(status.fileChecksum || '').toLowerCase();
if (!Number.isSafeInteger(expectedRecords) || expectedRecords < 0) throw new Error('Marketo status returned an invalid numberOfRecords');
if (!Number.isSafeInteger(expectedBytes) || expectedBytes <= 0) throw new Error('Marketo status returned an invalid fileSize');
if (!/^sha256:[0-9a-f]{64}$/.test(expectedChecksum)) throw new Error('Marketo status returned an invalid SHA-256 checksum');
const actualBytes = Buffer.byteLength(text, 'utf8');
const actualSha256 = createHash('sha256').update(text, 'utf8').digest('hex');
if (rows.length !== expectedRecords) throw new Error(`Marketo record-count mismatch: expected ${expectedRecords}, parsed ${rows.length}`);
if (actualBytes !== expectedBytes) throw new Error(`Marketo file-size mismatch: expected ${expectedBytes}, downloaded ${actualBytes}`);
if (`sha256:${actualSha256}` !== expectedChecksum) throw new Error('Marketo SHA-256 checksum mismatch');
const exportId = $('Create Export').item.json.result[0].exportId;
const scope = $('Loop Smart Lists').item.json;
return [{json:{
  payload_json: JSON.stringify({rows, export_id: exportId, window_start: scope.window_start, window_end: scope.window_end, segment_key: scope.segmentKey, smart_list_id: scope.smartListId, file_sha256: actualSha256, file_bytes: actualBytes, provider_number_of_records: expectedRecords}),
  export_id: exportId,
  segment_key: scope.segmentKey,
  smart_list_id: scope.smartListId,
  smart_list_name: scope.smartListName,
  provider_rows: expectedRecords,
  file_sha256: actualSha256,
  file_bytes: actualBytes
}}];

const now = $now.toUTC();
return [{json:{
  window_start: now.minus({seconds:1}).toFormat("yyyy-MM-dd'T'HH:mm:ss'Z'"),
  window_end: now.toFormat("yyyy-MM-dd'T'HH:mm:ss'Z'")
}}];
